<script setup lang="ts">import {Head,Link,useForm} from '@inertiajs/vue3';const props=defineProps<{templates:Record<string,string>,variables:string[]}>();const form=useForm({templates:{...props.templates}});</script><template><Head title="Template Notifikasi"/><main class="min-h-screen bg-slate-100 p-5"><form @submit.prevent="form.put('/admin/notification-templates')" class="mx-auto max-w-3xl space-y-5 rounded-2xl bg-white p-7"><Link href="/admin/dashboard" class="text-emerald-700">← Dashboard</Link><h1 class="text-3xl font-bold text-emerald-950">Template notifikasi</h1><p class="text-sm text-slate-600">Variabel: {{variables.join(', ')}}</p><label v-for="(_,event) in form.templates" :key="event" class="block"><span class="font-semibold">{{String(event).replaceAll('_',' ')}}</span><textarea v-model="form.templates[event]" rows="3" class="mt-1 w-full rounded-xl border-slate-300"></textarea></label><button class="w-full rounded-xl bg-emerald-800 py-3 font-bold text-white">Simpan template</button></form></main></template>
